// Closest Java equivalent: a javac annotation processor
@SupportedAnnotationTypes("workbench.ksp.annotations.Inventory")
@SupportedOptions({"movemate.listName", "movemate.listPackage"})
public class MasterListProcessor extends AbstractProcessor {
    private boolean written;

    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        if (written || roundEnv.processingOver()) return false;
        String listName = processingEnv.getOptions().get("movemate.listName");          // the job sheet
        String pkg = processingEnv.getOptions().getOrDefault("movemate.listPackage", "movemate");
        List<Element> classes = new ArrayList<>(roundEnv.getElementsAnnotatedWith(Inventory.class));
        if (listName == null || classes.isEmpty()) return false;
        try (Writer out = processingEnv.getFiler()
                .createSourceFile(pkg + "." + listName, classes.toArray(new Element[0]))  // every origin
                .openWriter()) {
            out.write(listSource(pkg, listName, classes));
        } catch (IOException e) {
            processingEnv.getMessager().printMessage(Diagnostic.Kind.ERROR, e.toString());
        }
        written = true;
        return false;
    }
}
// META-INF/gradle/incremental.annotation.processors:
//   workbench.ksp.l07.MasterListProcessor,aggregating

