class MasterListProcessor(
    private val codeGenerator: CodeGenerator,
    private val logger: KSPLogger,
    private val options: Map<String, String>,
) : SymbolProcessor {
    override val apiFeatures = buildApiFeatures { enableBackingFields = true; enableContextParameters = true }
    private var listWritten = false

    override fun process(resolver: Resolver): List<KSAnnotated> {
        if (listWritten) return emptyList()
        val listOptions = readListOptions(options, logger) ?: return emptyList()          // the job sheet
        val classes = resolver.getSymbolsWithAnnotation("workbench.ksp.annotations.Inventory")
            .filterIsInstance<KSClassDeclaration>().toList()
        if (classes.isEmpty()) return emptyList()
        masterListFile(classes, listOptions)
            .writeTo(codeGenerator, Dependencies(aggregating = true, *classes.mapNotNull { it.containingFile }
                .distinct().toTypedArray()))                                                   // every origin
        listWritten = true
        return emptyList()
    }
}

